using Situ.Domain.Common;

namespace Situ.Domain.Identity;

/// <summary>
/// A device (phone or browser) with an active login. The number of active devices per account is limited
/// by plan (RF-AUT-10); the web counts as one device. Also holds the push token for notifications.
/// </summary>
public sealed class UserDevice : AuditableEntity
{
    private UserDevice()
    {
        DeviceIdentifier = null!;
    }

    public Guid UserId { get; private set; }

    /// <summary>Stable identifier generated by the client app (not a hardware id).</summary>
    public string DeviceIdentifier { get; private set; }

    public DevicePlatform Platform { get; private set; }
    public string? DeviceName { get; private set; }
    public string? AppVersion { get; private set; }
    public string? PushToken { get; private set; }
    public DateTimeOffset LastSeenAt { get; private set; }
    public string? LastIpAddress { get; private set; }
    public DateTimeOffset? RevokedAt { get; private set; }

    public bool IsActive => RevokedAt is null;

    public static UserDevice Register(
        Guid userId,
        string deviceIdentifier,
        DevicePlatform platform,
        string? deviceName,
        string? appVersion,
        string? ipAddress,
        DateTimeOffset now)
    {
        var device = new UserDevice
        {
            UserId = Guard.NotEmpty(userId, nameof(userId)),
            DeviceIdentifier = Guard.NotEmpty(deviceIdentifier, nameof(deviceIdentifier), 128),
            Platform = platform,
            DeviceName = Guard.Optional(deviceName, nameof(deviceName), 100),
            AppVersion = Guard.Optional(appVersion, nameof(appVersion), 30),
            LastIpAddress = Guard.Optional(ipAddress, nameof(ipAddress), 64),
            LastSeenAt = now,
        };
        device.MarkCreated(now);
        return device;
    }

    public void Touch(DateTimeOffset now, string? ipAddress)
    {
        LastSeenAt = now;
        LastIpAddress = Guard.Optional(ipAddress, nameof(ipAddress), 64) ?? LastIpAddress;
    }

    public void UpdatePushToken(string? pushToken) => PushToken = Guard.Optional(pushToken, nameof(pushToken), 512);

    /// <summary>Remote sign-out ("Mis dispositivos").</summary>
    public void Revoke(DateTimeOffset now)
    {
        RevokedAt ??= now;
        PushToken = null;
    }

    /// <summary>The user signs in again from the same device.</summary>
    public void Reactivate(DateTimeOffset now)
    {
        RevokedAt = null;
        LastSeenAt = now;
    }
}
